//! 📦️ Package glue — wiring only. Domain lives at the owner `🦀️.rs` files.
//!
//! The crate's `[lib] name` is `pack`: the container format keeps the one canonical name every
//! downstream caller already spells.

// 🔓️ R7: `async fn` in a public trait is our deliberate crate-wide shape (R3 answers the lint's
// underlying `Send` concern structurally — see `AsyncPackSource`/`RangeTransport`). Never take
// rustc's suggested `-> impl Future<...> + Send` fix; it re-imposes `Send` R3 forbids.
#![allow(async_fn_in_trait)]
#![allow(ambiguous_glob_reexports, unused_imports)]

// 📡️ Codec primitives, container identity and pack sources are owned by the replication module —
// the `.spk` container and the `.spr` record stream share one codec floor.
pub use protocol::codec;
pub use protocol::codec::ids;
pub use protocol::source;
/// 🌱️ Re-exported so a crate that already depends on `pack` (e.g. `🏗️mesh-engine`) can implement
/// `ToValue`/`FromValue` for its own types without taking a second, direct dependency on
/// `replication` — implementing a foreign trait for a local type is allowed by the orphan rule.
pub use protocol::value;

#[path = "../../📐️format/🦀️.rs"]
pub mod format;

#[path = "../../🔤️json/🦀️.rs"]
pub mod json;

#[path = "../../⏳️async/🦀️.rs"]
pub mod async_;

#[path = "../../🌐️http/🦀️.rs"]
pub mod http;

#[cfg(not(target_arch = "wasm32"))]
#[path = "../../🔌️io/🦀️.rs"]
pub mod io;

#[cfg(any(test, feature = "corruption-testing"))]
#[path = "../../🧪️tests/🧨️corruption/🦀️.rs"]
pub mod corruption_testing;

#[path = "../../🦀️.rs"]
mod component;
pub use component::*;

pub use protocol::codec::ids::*;
pub use protocol::codec::*;
pub use protocol::source::*;

//! 📦️ `pack` — the facade crate for the `pack` binary document format family: re-exports the
//! full public surface of `pack_core`, `pack_format`, `pack_value`, `pack_io` (native-only,
//! cfg-gated out on `wasm32`), `pack_async`, `pack_http`, and `pack_index` under one crate so
//! downstream callers (`vcs`, `dsl_derive`, apps) depend on a single `pack = { path = ... }`
//! rather than seven. Also exposes three top-level convenience functions —
//! `encode_document`/`decode_document`/`content_hash` — that are thin forwards onto
//! `pack_value`/`pack_format`.
//!
//! See the `## pack (facade)` section of the wave-0 contract at
//! `.🧬semio/🦑️repo/🎫️tickets/26/07/27/PACK-BINARY-DOCUMENT-LAYER-ACROSS-ALL-APPS/contract.md`. This crate does
//! NOT re-export `dsl_schema` itself as `crate::dsl_schema` — callers pass in
//! `&os_dsl::schema::RecordSpec`/`&os_dsl::schema::RecordValue` they already depend on directly.

//#region 🔖️Reexports

//#region 🔖️Core
pub use crate::{
    crc32c, is_minimal_varint, read_varint_i64, read_varint_u64, write_varint_i64, write_varint_u64, ByteRange, ByteReader, ByteWriter, ChunkId, CodecId, CompressionCodec, ContentHash, NoCompression, PackError, PackLimits, PackSink, PackSource,
    SegmentKind, KIND_CHUNK, KIND_CHUNK_TABLE, KIND_DOCUMENT, KIND_END, KIND_FIELD_INDEX, KIND_MANIFEST, KIND_PADDING, KIND_SCHEMA, KIND_SNAPSHOT, KIND_SYMBOLS,
};

/// 🆔️ Computes the canonical pack content identity for `bytes`.
pub fn content_hash(bytes: &[u8]) -> ContentHash {
    ContentHash(*semio_framework_hash::hash(bytes).as_bytes())
}
//#endregion 🔖️Core

//#region 🔖️Format
#[cfg(feature = "deflate")]
pub use crate::codec::DeflateCodec;
pub use crate::format::{
    encode_symbols, read_footer_only, recover, Footer, Header, Manifest, PackFile, PackIdentitySegment, PackWriter, RecoveryReport, RetainedPackAnchorCursor, RetainedPackCatalog, RetainedPackCatalogAllocationError,
    RetainedPackCatalogAllocationStep, RetainedPackCatalogCursor, RetainedPackCatalogEvent, RetainedPackCatalogFault, RetainedPackCatalogProgress, RetainedPackChunkEntry, RetainedPackManifest, RetainedPackSymbolSpan,
    RetainedPackCloseStep, RetainedPackPage, RetainedPackSegmentCursor, RetainedPackSegmentEvent, RetainedPackSegmentHeader, RetainedPackSourceAllocationError,
    RetainedPackSourceAllocationStep, RetainedPackSourceCursor, RetainedPackSourceEvent, RetainedPackSourceProgress, Superblock, RETAINED_PACK_MAXIMUM_PAGES,
    VerificationLevel, WriteOptions, FOOTER_MAGIC, FOOTER_SIZE, FORMAT_VERSION_MAJOR, FORMAT_VERSION_MINOR, HEADER_SIZE, MAGIC, OPTIONAL_CANONICAL, OPTIONAL_HAS_SCHEMA, OPTIONAL_STREAMED, REQUIRED_CHUNKED, REQUIRED_COMPRESSED, REQUIRED_ENCRYPTED,
    REQUIRED_FOOTER_CHAIN, RETAINED_PACK_PAGE_BYTES,
};
//#endregion 🔖️Format

//#region 🔖️Json
pub use crate::json::{
    array as json_array, from_dsl_value as json_from_dsl_value, from_json_str, object as json_object, parse as parse_json, parse_bytes as parse_json_bytes, to_dsl_value as json_to_dsl_value, to_json_string, to_string as json_to_string,
    to_string_pretty as json_to_string_pretty, JsonError, Lexer as JsonLexer, Number as JsonNumber, Object as JsonObject, Token as JsonToken, Value as JsonValue, MAX_DEPTH as JSON_MAX_DEPTH,
};
//#endregion 🔖️Json

//#region 🔖️Io
/// 🗄️ Native-only file I/O — absent from `wasm32` builds, mirroring `pack_io` itself.
#[cfg(not(target_arch = "wasm32"))]
pub use crate::io::{recover_file, write_atomic, FilePackSink, FilePackSource, StreamingPackWriter};
//#endregion 🔖️Io

//#region 🔖️Async
pub use crate::async_::{AsyncPackSource, BoundedDemand, CancellationToken, DemandPermit, LoadPriority, ReadRequest, ReadScheduler};
//#endregion 🔖️Async

//#region 🔖️Http
/// 🌐️ Native `ureq`-backed `RangeTransport` — off by default so wasm builds of this
/// facade stay lean; enable via `pack`'s own `ureq` feature (forwards to `pack_http/ureq`).
#[cfg(feature = "ureq")]
pub use crate::http::UreqRangeTransport;
pub use crate::http::{HttpPackSource, RangeRequest, RangeResponse, RangeTransport, RetryPolicy, RetryRuntime};
//#endregion 🔖️Http

//#endregion 🔖️Reexports

