//#region 🔖️MediaExport
/// 🧵️ Collects every distinct brep geometry handle exposed by the fixture's preview-flagged widgets, evaluated against the current param overrides — same eval pass as `evaluated_preview_payload`, minus the tessellation step.
fn evaluated_preview_geometry_handles(owner: &mut ModuleGeometryOwner, host_snapshot: &FlowHostSnapshot, params: &Value) -> Vec<String> {
    let mut host = match owner.host(host_snapshot.clone()) {
        Ok(host) => host,
        Err(_) => return Vec::new(),
    };
    apply_flow_params(&mut host, host_snapshot, params);
    let eval_json = host.evaluate().unwrap_or_default();
    let eval: Value = parse_json(&eval_json).unwrap_or(semio_framework_pack_json::json!({}));
    let mut handles: Vec<String> = Vec::new();
    for widget in &host_snapshot.widgets {
        let id = widget_id(widget).to_string();
        let preview = matches!(widget, Widget::Neuron { preview: true, .. } | Widget::OutputPreview { .. });
        if !preview {
            continue;
        }
        if let Some(handle) = geometry_handle_for_widget(&eval, &id) {
            if !handles.contains(&handle) {
                handles.push(handle);
            }
        }
    }
    owner.retain_current(&handles);
    host.retire_cold();
    handles
}

/// 📤️ Handles `Command::ExportSolid`: re-evaluates the active host_snapshot, exports every preview geometry handle through `flow` brep geometry session's STEP/OBJ/STL kernel codecs (GLB bridges through mesh tessellation), and stashes the JSON result on `params.__solidExport` for the host shell to read back.
fn handle_export_solid(owner: &mut ModuleGeometryOwner, payload: &mut ModuleRenderPayload, format: &str) {
    let slug = if payload.fixture_slug.is_empty() { "hexagonal-mushroom-column" } else { payload.fixture_slug.as_str() };
    let Some(fixture_json) = fixture_json_for_slug(slug) else {
        return;
    };
    let host_snapshot: FlowHostSnapshot = semio_framework_pack_json::from_json_str(fixture_json).unwrap_or_else(|_| FlowHostSnapshot::default());
    let params = params_as_json(&payload.params);
    let mut handles = evaluated_preview_geometry_handles(owner, &host_snapshot, &params);
    if let Ok(imported) = imported_geometry_handles(owner, &params) {
        for handle in imported { if !handles.contains(&handle) { handles.push(handle); } }
    }
    // 🧊️ Closed, never dropped — see `evaluated_preview_payload`.
    host_snapshot.retire_cold();
    owner.retain_current(&handles);
    let result_json =
        if handles.is_empty() { semio_framework_pack_json::json!({ "error": "no procedural solid geometry to export" }) } else { parse_json(&owner.session.export_solid_json(&handles, format, SOLID_EXPORT_DEFLECTION)).unwrap_or(semio_framework_pack_json::json!({ "error": "export failed" })) };
    let mut object = params_as_json(&payload.params);
    let Some(map) = object.as_object_mut() else {
        return;
    };
    map.insert("__solidExport", result_json);
    payload.params = json_to_dsl_value(&object);
}

/// 📥️ Handles `Command::ImportSolid`: imports `data` (UTF-8 text for STEP/OBJ, base64 for STL/GLB) as `format` through `flow` brep geometry session's in-process kernel (GLB bridges through mesh tessellation into an OBJ ingestion) and persists the replayable interchange source on `params.__solidImport`.
fn handle_import_solid(owner: &mut ModuleGeometryOwner, payload: &mut ModuleRenderPayload, format: &str, data: &str) {
    let source = semio_framework_pack_json::json!({ "format": format, "data": data, "tolerance": SOLID_IMPORT_TOLERANCE });
    let params = semio_framework_pack_json::json!({ "__solidImport": source });
    let result_json = if data.is_empty() { semio_framework_pack_json::json!({ "error": "no import data provided" }) } else {
        match imported_geometry_handles(owner, &params) {
            Ok(_) => source,
            Err(_) => semio_framework_pack_json::json!({ "error": "import failed" }),
        }
    };
    let mut object = params_as_json(&payload.params);
    let Some(map) = object.as_object_mut() else {
        return;
    };
    map.insert("__solidImport", result_json);
    payload.params = json_to_dsl_value(&object);
}

fn imported_geometry_handles(owner: &mut ModuleGeometryOwner, params: &Value) -> Result<Vec<String>, Fault> {
    let Some(source) = params.get("__solidImport").filter(|source| source.get("error").is_none()) else {
        owner.retire_import_cache();
        return Ok(Vec::new());
    };
    let source_json = json_to_string(source);
    if let Some(cache) = &owner.imported {
        if cache.source == source_json { return Ok(cache.handles.clone()); }
    }
    owner.retire_import_cache();
    let format = source.get("format").and_then(Value::as_str).ok_or_else(|| Fault::from("playbook.module.procedural.import-source-format"))?;
    let data = source.get("data").and_then(Value::as_str).ok_or_else(|| Fault::from("playbook.module.procedural.import-source-data"))?;
    let tolerance = source.get("tolerance").and_then(Value::as_f64).ok_or_else(|| Fault::from("playbook.module.procedural.import-source-tolerance"))?;
    let result = parse_json(&owner.session.import_solid_json(format, data, tolerance)).map_err(|_| Fault::from("playbook.module.procedural.import-source-invalid"))?;
    if result.get("error").is_some() { return Err(Fault::from("playbook.module.procedural.import-source-failed")); }
    let values = result.get("handles").and_then(Value::as_array).ok_or_else(|| Fault::from("playbook.module.procedural.import-handles-missing"))?;
    let handles: Vec<String> = values.iter().map(|value| value.as_str().filter(|handle| is_brep_geometry_handle(handle)).map(str::to_owned).ok_or_else(|| Fault::from("playbook.module.procedural.import-handle-invalid"))).collect::<Result<_, _>>()?;
    owner.retire_import_cache();
    owner.imported = Some(ModuleImportedGeometry { source: source_json, handles: handles.clone() });
    Ok(handles)
}

fn media_button(payload: &ModuleRenderPayload, format: &str, import: bool) -> UiAssemblyResult<BuiltNode> {
    let verb = if import { "Import" } else { "Export" };
    let icon = if import { "import" } else { "export" };
    let label = format!("{verb} {}", format.to_uppercase());
    bind_control(
        button(ui_label(&label)?).icon(ui_text(icon)?),
        &format!("playbook-module.{icon}.{format}"),
        &label,
        payload,
        if import { ACTION_IMPORT_SOLID } else { ACTION_EXPORT_SOLID },
        value_map([("format", value_text(format)?)])?,
        Trigger::Activate,
    )
}

fn render_question_control(question: &PlaybookBlock, value: &Value, payload: &ModuleRenderPayload, parent_window: Option<(&str, &str)>) -> UiAssemblyResult<BuiltNode> {
    let key = question.id.as_str();
    let mut ids = UiListBuilder::try_new().ok_or_else(|| PluginAssemblyError::new("ui.fixed-capacity", "procedural question ids admission failed"))?;
    ui_admit(ids.push(value_text(&payload.question_id)?))?;
    let blueprint = payload.surface == "blueprint";
    let mut args = vec![("questionIds", UiValue::List(ids.finish())), ("field", value_text(if blueprint { "param" } else { "tryParam" })?), ("paramKey", value_text(key)?), ("key", value_text(&payload.question_id)?)];
    if let Some((id, kind)) = parent_window {
        args.extend([("windowId", value_text(id)?), ("windowKindId", value_text(kind)?)]);
    }
    let args = value_map(args)?;
    let control: BuiltNode = match question.kind.as_str() {
        "text" | "longText" | "number" => {
            let kind = match question.kind.as_str() {
                "longText" => InputKind::LongText,
                "number" => InputKind::Number,
                _ => InputKind::Text,
            };
            let mut input = input(kind).value(ui_text(json_string_value(value))?);
            if let Some(placeholder) = &question.placeholder {
                input = input.placeholder(ui_label(placeholder)?);
            }
            input.into()
        }
        "slider" => slider(json_f64_value(value)).min(question.min.unwrap_or(0.0)).max(question.max.unwrap_or(100.0)).step(question.step.unwrap_or(1.0)).into(),
        "boolean" => toggle(value.as_bool().unwrap_or(false)).icon(ui_text("check")?).into(),
        _ => return text_node(format!("Unsupported param kind: {}", question.kind)),
    };
    let control = bind_control(control, &format!("playbook-module.{key}.input"), &question.label, payload, if blueprint { "patchQuestions" } else { "setTryValue" }, args, Trigger::Change)?;
    let field = ui_admit(field(ui_label(&question.label)?).try_id(format!("playbook-module.{key}")))?;
    ui_admit(ui_admit(field.try_child(control))?.try_build())
}

fn render_params_body(payload: &ModuleRenderPayload, labels: &ModuleLabels, parent_window: Option<(&str, &str)>, embedded: bool) -> UiAssemblyResult<BuiltNode> {
    let slug = if payload.fixture_slug.is_empty() { "hexagonal-mushroom-column" } else { payload.fixture_slug.as_str() };
    let Some(fixture_json) = fixture_json_for_slug(slug) else {
        return text_node(format!("Unknown fixture slug: {slug}"));
    };
    let host_snapshot: FlowHostSnapshot = semio_framework_pack_json::from_json_str(fixture_json).map_err(|error| PluginAssemblyError::new("procedural.fixture", error.to_string()))?;
    let spec = flow_host_snapshot_to_form_spec(&host_snapshot);
    // 🧊️ `spec` is an OWNED form projection, so the decoded fixture is done here — closed, never
    // dropped (see `evaluated_preview_payload`). Retired BEFORE the `?`-returning body below so no
    // early exit can leak it.
    host_snapshot.retire_cold();
    let values: Map = params_as_json(&payload.params).as_object().cloned().unwrap_or_default();
    let Some(step) = spec.steps.first() else {
        return text_node(labels.no_flow_inputs.as_str());
    };
    let values_dsl: HashMap<String, DslValue> = values.iter().map(|(key, value)| (key.to_string(), json_to_dsl_value(value))).collect();
    let visible = visible_blocks(step, &values_dsl);
    let mut column = column();
    if visible.is_empty() {
        column = ui_admit(column.try_child(text_node(labels.no_procedural_parameters.as_str())?))?;
    }
    for question in visible {
        let value = values.get(&question.id).cloned().unwrap_or_else(|| question.default.as_ref().map(json_from_dsl_value).unwrap_or(Value::Null));
        column = ui_admit(column.try_child(render_question_control(question, &value, payload, parent_window)?))?;
    }
    for format in SOLID_MEDIA_FORMATS.into_iter().filter(|_| !embedded) {
        column = ui_admit(column.try_child(media_button(payload, format, false)?))?;
        column = ui_admit(column.try_child(media_button(payload, format, true)?))?;
    }
    ui_admit(column.try_build())
}

fn embedded_payload(input: &str, body_key: &str) -> UiAssemblyResult<(ModuleRenderPayload, Option<(String, String)>)> {
    let error = || PluginAssemblyError::new("procedural.extension-input", "invalid embedded surface input");
    let props = parse_json(input).map_err(|_| error())?;
    if props.get("bodyKey").and_then(Value::as_str) != Some(body_key) { return Err(error()); }
    let json = props.get("paramsJson").and_then(Value::as_str).ok_or_else(error)?;
    let payload: ModuleRenderPayload = semio_framework_pack_json::from_json_str(json).map_err(|_| error())?;
    let target = parse_json(json).map_err(|_| error())?;
    let window = match (target.get("windowId").and_then(Value::as_str), target.get("windowKindId").and_then(Value::as_str)) {
        (None, None) => None,
        (Some(id), Some(kind)) if !id.is_empty() && !kind.is_empty() && payload.surface == "try" => Some((id.to_string(), kind.to_string())),
        _ => return Err(error()),
    };
    if payload.question_id.is_empty() || payload.controller_id.is_empty() || !matches!(payload.surface.as_str(), "blueprint" | "try") { return Err(error()); }
    Ok((payload, window))
}
